package dev.pedro.learning.ecommerce.notification.event;import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.enterprise.context.ApplicationScoped;@ApplicationScoped public class EventJson{private final ObjectMapper mapper;public EventJson(ObjectMapper mapper){this.mapper=mapper;}public RawEventEnvelope parseRaw(String json){try{return mapper.readValue(json,RawEventEnvelope.class);}catch(JsonProcessingException e){throw new IllegalArgumentException("Invalid event JSON",e);}}public <T> EventEnvelope<T> toTyped(RawEventEnvelope raw,Class<T> type){try{return new EventEnvelope<>(raw.eventId(),raw.correlationId(),raw.eventType(),raw.occurredAt(),raw.schemaVersion(),mapper.treeToValue(raw.payload(),type));}catch(JsonProcessingException e){throw new IllegalArgumentException("Invalid event payload",e);}}public String write(Object value){try{return mapper.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException("Could not serialize event",e);}}}